/* Shared stamp renderer: the passport exports the exact same stamp images as the UI. */
(function(){
 const C=window.BITE_CONTENT,P=C.passport,ink=P.colors.ink,paper=P.colors.paper;
 const imageCache=new Map(),stampCache=new Map();
 function image(src){if(!imageCache.has(src))imageCache.set(src,new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>{imageCache.delete(src);reject(Error('Artwork could not load. Please retry.'))};im.src=src}));return imageCache.get(src)}
 function canvas(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;return c}
 function type(ctx,text,x,y,size,max,color=ink,align='left',weight=700){ctx.fillStyle=color;ctx.textAlign=align;while(size>12){ctx.font=`${weight} ${size}px "Zen Maru Gothic", sans-serif`;if(ctx.measureText(text).width<=max)break;size--}ctx.fillText(text,x,y);}
 function lines(ctx,text,x,y,width,size,lineHeight,maxLines=4,color=ink){ctx.font=`500 ${size}px "Zen Maru Gothic", sans-serif`;ctx.fillStyle=color;ctx.textAlign='left';const words=text.split(/\s+/);let line='',n=0;for(let i=0;i<words.length;i++){const next=line?line+' '+words[i]:words[i];if(ctx.measureText(next).width>width&&line){ctx.fillText(line,x,y+n*lineHeight);n++;line=words[i];if(n===maxLines-1){let rest=[line,...words.slice(i+1)].join(' ');while(ctx.measureText(rest).width>width&&rest.length)rest=rest.slice(0,-1);if(i<words.length-1)rest=rest.trimEnd()+'…';ctx.fillText(rest,x,y+n*lineHeight);return n+1;}}else line=next;}if(line)ctx.fillText(line,x,y+n*lineHeight);return n+1}
 function round(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=3;ctx.stroke()}}
 async function stamp(code){if(stampCache.has(code))return stampCache.get(code);const task=(async()=>{await document.fonts.ready;const s=C.cuisine(code),c=canvas(P.stampWidth,P.stampHeight),ctx=c.getContext('2d'),w=c.width,h=c.height;round(ctx,9,9,w-18,h-18,10,paper,ink);ctx.strokeStyle=P.colors.coral;ctx.lineWidth=3;ctx.setLineDash([3,7]);ctx.strokeRect(22,22,w-44,h-44);ctx.setLineDash([]);type(ctx,'BITE QUEST • NEW YORK',w/2,54,15,w-60,ink,'center');
 if(s.slot!==undefined){const im=await image(s.artPath),sw=im.width/C.stampArt.columns,sh=im.height/C.stampArt.rows;ctx.save();ctx.beginPath();ctx.roundRect(34,70,w-68,270,8);ctx.clip();const scale=Math.min((w-68)/sw,270/sh),dw=sw*scale,dh=sh*scale;ctx.drawImage(im,(s.slot%C.stampArt.columns)*sw,Math.floor(s.slot/C.stampArt.columns)*sh,sw,sh,(w-dw)/2,70+(270-dh)/2,dw,dh);ctx.restore();}else{const im=await image('rat-chef.png');ctx.globalAlpha=.42;ctx.drawImage(im,110,91,180,180);ctx.globalAlpha=1;type(ctx,'RECIPE TO DISCOVER',w/2,314,17,w-60,ink,'center');}
 type(ctx,s.label,w/2,377,29,w-52,ink,'center',900);type(ctx,s.dish||'A future food discovery',w/2,410,16,w-50,P.colors.muted,'center',500);return c;})();stampCache.set(code,task);task.catch(()=>stampCache.delete(code));return task}
 function hydrate(){document.querySelectorAll('img[data-cuisine-stamp]').forEach(el=>{if(el.dataset.loading)return;el.dataset.loading='true';stamp(el.dataset.cuisineStamp).then(c=>{if(!el.isConnected)return;el.src=c.toDataURL('image/png');el.hidden=false;el.parentElement.querySelector('.stamp-loading')?.remove()}).catch(()=>{delete el.dataset.loading;const fallback=el.parentElement.querySelector('.stamp-loading');if(fallback)fallback.textContent=C.cuisine(el.dataset.cuisineStamp).label+' · Artwork unavailable';})})}
 async function render({kind,earned,featured,visited,trail}){await document.fonts.ready;const c=canvas(P.width,P.height),ctx=c.getContext('2d'),w=c.width;ctx.fillStyle=paper;ctx.fillRect(0,0,w,c.height);ctx.fillStyle=ink;ctx.fillRect(0,0,w,250);ctx.fillStyle=P.colors.gold;ctx.fillRect(0,246,w,5);type(ctx,'BITE QUEST / NEW YORK CITY',64,75,26,w-128,paper);type(ctx,kind==='business'?'A BITE WORTH SHARING.':'MY FOOD PASSPORT.',64,148,52,w-128,paper);type(ctx,kind==='business'?(visited?'A discovery from my table':'Next on my list'):`${earned.length} cuisine${earned.length===1?'':'s'} discovered • one curious city`,64,203,25,w-128,P.colors.gold);
 const codes=kind==='business'?featured.countryCodes:earned.slice(0,P.maxStamps);
 if(kind==='business'){
 const code=codes[0];if(code){const art=await stamp(code);ctx.save();ctx.translate(355,300);ctx.rotate(-.04);ctx.drawImage(art,0,0,370,426);ctx.restore();}else{const owl=await image('rat-chef.png');ctx.drawImage(owl,350,310,370,370);}
 type(ctx,visited?'FOUND & SAVORED':'WANT TO TRY',w/2,746,18,w-128,P.colors.coral,'center');
 }else{
 if(codes.length){const cols=Math.min(3,codes.length),sw=codes.length===1?420:codes.length<=3?280:245,sh=sw*P.stampHeight/P.stampWidth,gap=45,total=cols*sw+(cols-1)*gap;for(let i=0;i<codes.length;i++){const art=await stamp(codes[i]);const x=(w-total)/2+(i%cols)*(sw+gap),y=(codes.length<=3?310:282)+Math.floor(i/cols)*306;ctx.save();ctx.translate(x+sw/2,y+sh/2);ctx.rotate((i%2?1:-1)*.025);ctx.drawImage(art,-sw/2,-sh/2,sw,sh);ctx.restore();}if(codes.length<=3)type(ctx,codes.length===1?'ONE FIRST BITE. A WHOLE CITY AHEAD.':'GOOD TASTE. NEW CORNERS OF THE CITY.',w/2,855,24,w-128,P.colors.coral,'center');}
 else{const owl=await image('rat-chef.png');ctx.drawImage(owl,398,300,280,280);type(ctx,'My first stamp is a meal away.',w/2,638,32,w-128,ink,'center');}
 }
 const boxY=kind==='business'?770:922;round(ctx,54,boxY,w-108,kind==='business'?370:275,18,'#FFFFFF',null);type(ctx,kind==='business'?'THE KITCHEN BEHIND THE STAMP':'NEXT STOP / GO WITH A FRIEND',80,boxY+40,17,w-160,P.colors.coral);type(ctx,featured.name,80,boxY+94,41,w-160);type(ctx,featured.signatureDish,80,boxY+137,27,w-160);type(ctx,`${featured.area} • ${featured.address}`,80,boxY+177,23,w-160,P.colors.muted, 'left',500);
 if(kind==='business')lines(ctx,featured.story,80,boxY+223,w-160,24,35,4);
 if(kind!=='business')type(ctx,`${trail.name} • ${trail.have}/${trail.goal}`,80,boxY+230,24,w-160,ink);
 type(ctx,'Walk in for the food. Come back for the story.',64,1230,26,w-128,ink);type(ctx,'Find this kitchen: bite-quest-nyc-rm.meyer-rebecca-chs.chatgpt.site/?business='+featured.id,64,1273,17,w-128,P.colors.muted,'left',500);type(ctx,`Demo passport • ${visited?'dining logs are simulated':'no dining visit claimed'}${earned.length>P.maxStamps&&kind!=='business'?` • ${P.maxStamps} of ${earned.length} stamps shown`:''}`,64,1315,18,w-128,P.colors.muted,'left',500);
 return {canvas:c,blob:await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('Image export failed')),'image/png'))};}
 function delivery(canShare,file){try{return canShare&&canShare({files:[file]})?'native-image':'download'}catch{return 'download'}}
 window.BITE_PASSPORT={stamp,hydrate,render,delivery};
})();
